import urllib.request
import json

# Get some more AI news sources
urls = {
    "HackerNews_AI": "https://hn.algolia.com/api/v1/search?query=AI+OR+LLM+OR+AGI+OR+%22AI+agent%22&tags=story&hitsPerPage=15&numericFilters=created_at_i>1745625600",
    "VentureBeat_AI": "https://hn.algolia.com/api/v1/search?query=site:venturebeat.com+AI+OR+LLM&tags=story&hitsPerPage=10&numericFilters=created_at_i>1745625600",
}

all_data = {}
for name, url in urls.items():
    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            data = json.loads(resp.read().decode())
            hits = data.get('hits', [])
            all_data[name] = hits
            print(f"=== {name} ({len(hits)} results) ===")
            for h in hits[:8]:
                title = h.get('title', '')[:80]
                pts = h.get('points', 0)
                url_short = h.get('url', '')[:60] if h.get('url') else 'HN'
                print(f"  [{pts}pts] {title}")
                if url_short != 'HN':
                    print(f"           {url_short}")
            print()
    except Exception as e:
        print(f"{name} Error: {e}")

# Save all collected data
with open('/tmp/ai_news_all.json', 'w', encoding='utf-8') as f:
    json.dump(all_data, f, ensure_ascii=False)
"}

